class DraftStore:
    """Small per-user SQLite store for draft listings; no FunPay credentials are stored."""

    def __init__(self, filename: str) -> None:
        self.path = Path(filename)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        with self._connect() as db:
            db.execute("""
                CREATE TABLE IF NOT EXISTS drafts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER NOT NULL,
                    title TEXT NOT NULL,
                    category TEXT NOT NULL,
                    price TEXT NOT NULL,
                    details TEXT NOT NULL,
                    delivery TEXT NOT NULL,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                )
            """)
            db.execute("CREATE INDEX IF NOT EXISTS idx_drafts_user ON drafts(user_id, id DESC)")

    def _connect(self) -> sqlite3.Connection:
        db = sqlite3.connect(self.path, timeout=20)
        db.row_factory = sqlite3.Row
        return db

    def create(self, user_id: int, draft: dict[str, str]) -> int:
        with self.lock, self._connect() as db:
            row = db.execute("SELECT COUNT(*) AS n FROM drafts WHERE user_id=?", (user_id,)).fetchone()
            if int(row["n"]) >= MAX_DRAFTS_PER_USER:
                old = db.execute(
                    "SELECT id FROM drafts WHERE user_id=? ORDER BY id ASC LIMIT 1", (user_id,)
                ).fetchone()
                if old:
                    db.execute("DELETE FROM drafts WHERE id=? AND user_id=?", (old["id"], user_id))
            cur = db.execute(
                "INSERT INTO drafts(user_id,title,category,price,details,delivery) VALUES(?,?,?,?,?,?)",
                (user_id, draft["title"], draft["category"], draft["price"], draft["details"], draft["delivery"]),
            )
            return int(cur.lastrowid)

    def list_for_user(self, user_id: int) -> list[sqlite3.Row]:
        with self.lock, self._connect() as db:
            return list(db.execute(
                "SELECT id,title,category,price,created_at FROM drafts WHERE user_id=? ORDER BY id DESC LIMIT ?",
                (user_id, MAX_DRAFTS_PER_USER),
            ).fetchall())

    def get(self, user_id: int, draft_id: int) -> sqlite3.Row | None:
        with self.lock, self._connect() as db:
            return db.execute(
                "SELECT * FROM drafts WHERE user_id=? AND id=?", (user_id, draft_id)
            ).fetchone()

    def delete(self, user_id: int, draft_id: int) -> bool:
        with self.lock, self._connect() as db:
            cur = db.execute("DELETE FROM drafts WHERE user_id=? AND id=?", (user_id, draft_id))
            return cur.rowcount > 0


