def clean_text(value: str, limit: int) -> str:
    value = value.replace("\x00", "").strip()
    if len(value) > limit:
        raise ValueError(f"Слишком длинный текст. Максимум — {limit} символов.")
    if not value:
        raise ValueError("Поле не должно быть пустым.")
    return value


def price_string(raw: str) -> str:
    candidate = raw.strip().replace(" ", "").replace(",", ".")
    if not re.fullmatch(r"\d{1,9}(?:\.\d{1,2})?", candidate):
        raise ValueError("Введи цену числом, например 150 или 150.50.")
    try:
        amount = Decimal(candidate)
    except InvalidOperation as exc:
        raise ValueError("Не удалось прочитать цену. Пример: 150.") from exc
    if amount <= 0:
        raise ValueError("Цена должна быть больше нуля.")
    return f"{amount:.2f}".rstrip("0").rstrip(".")


def format_draft(row: Any) -> str:
    return (
        f"Черновик #{row['id']}\n\n"
        f"Название: {row['title']}\n"
        f"Категория / игра: {row['category']}\n"
        f"Цена: {row['price']} ₽\n\n"
        f"Описание:\n{row['details']}\n\n"
        f"Выдача: {row['delivery']}\n\n"
        "Это сохранённый черновик — он ещё не опубликован на FunPay."
    )


async def send_scene(message: Any, scene: str, caption: str | None = None) -> None:
    encoded = SCENE_IMAGES_B64.get(scene)
    if not encoded:
        return
    try:
        photo = io.BytesIO(base64.b64decode(encoded))
        photo.name = f"funpay_lister_{scene}.jpg"
        await message.reply_photo(photo=photo, caption=caption or BRAND)
    except Exception:
        log.exception("Could not send embedded scene '%s'", scene)


async def start(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    await send_scene(message, "welcome", "FUNPAY LISTER by nezzx")
    await message.reply_text(
        "Привет! Это FUNPAY LISTER by nezzx. Бот бесплатный и открыт для всех.\n\n"
        "Здесь можно собрать аккуратный текст лота, сохранить черновики и открыть официальный FunPay.\n\n"
        "Для подключения нажми «Подключить FunPay»: откроется одноразовая HTTPS-форма на сервере. "
        "Пароль не сохраняется в базе, а сессия шифруется. Не используй эту возможность, если не доверяешь владельцу сервиса. "
        "CAPTCHA/2FA может остановить вход; автопубликация лотов пока не включена.",
        reply_markup=main_keyboard(),
        disable_web_page_preview=True,
    )


async def connect_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Create a short-lived one-time link to the hosted HTTPS login form."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if auth_store.fernet is None:
        await message.reply_text(
            "Подключение отключено: в Render → Environment добавь SESSION_ENCRYPTION_KEY.\n"
            "Сгенерировать ключ: python -c \"from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())\""
        )
        return
    base_url = os.getenv("RENDER_EXTERNAL_URL", "").strip().rstrip("/")
    if not base_url.startswith("https://"):
        await message.reply_text(
            "Для безопасного входа нужен публичный HTTPS-адрес Render. После деплоя проверь RENDER_EXTERNAL_URL и повтори /connect."
        )
        return
    token = auth_store.make_token(user.id)
    connect_url = f"{base_url}/connect/{token}"
    await message.reply_text(
        "Открой защищённую страницу подключения и введи данные непосредственно там, не в чате. "
        "Ссылка одноразовая и действует 15 минут. Пароль не сохраняется; после входа сохраняется только зашифрованная сессия.\n\n"
        "Не пересылай эту ссылку другим людям.",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Открыть страницу подключения", url=connect_url)],
            [InlineKeyboardButton("Проверить статус", callback_data="funpay:status")],
        ]),
    )


async def status_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    status = auth_store.get_status(user.id)
    if not status:
        await message.reply_text(
            "FunPay не подключён. Нажми «Подключить FunPay».\n"
            "Статус подтверждается только после успешного входа и обнаружения сессионной cookie.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("Подключить FunPay", callback_data="funpay:connect")],
                [InlineKeyboardButton("← В меню", callback_data="home")],
            ]),
        )
        return
    connected = int(status.get("connected_at", 0))
    when = __import__("datetime").datetime.fromtimestamp(connected, __import__("datetime").timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    await message.reply_text(
        f"Сессия сохранена для аккаунта: {status['username']}\nПодключено: {when}\n\n"
        "Это подтверждает успешный вход при подключении; сессия может истечь или быть отозвана на FunPay.",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Переподключить", callback_data="funpay:connect")],
            [InlineKeyboardButton("Отключить сессию", callback_data="funpay:disconnect")],
            [InlineKeyboardButton("← В меню", callback_data="home")],
        ]),
    )


