async def start_draft(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    context.user_data["draft_form"] = {}
    await query.message.reply_text(
        "Создание черновика — шаг 1 из 5.\n\nВведи название лота (до 120 символов).\n\n/cancel — отмена"
    )
    return TITLE


async def draft_title(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    try:
        value = clean_text(update.effective_message.text, 120)
    except ValueError as exc:
        await update.effective_message.reply_text(str(exc))
        return TITLE
    context.user_data["draft_form"] = {"title": value}
    await update.effective_message.reply_text("Шаг 2 из 5. Напиши игру или категорию лота (до 80 символов).")
    return CATEGORY


async def draft_category(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    try:
        value = clean_text(update.effective_message.text, 80)
    except ValueError as exc:
        await update.effective_message.reply_text(str(exc))
        return CATEGORY
    context.user_data["draft_form"]["category"] = value
    await update.effective_message.reply_text("Шаг 3 из 5. Введи цену в рублях, например 150 или 150.50.")
    return PRICE


async def draft_price(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    try:
        value = price_string(update.effective_message.text)
    except ValueError as exc:
        await update.effective_message.reply_text(str(exc))
        return PRICE
    context.user_data["draft_form"]["price"] = value
    await update.effective_message.reply_text("Шаг 4 из 5. Опиши, что именно получит покупатель (до 1500 символов).")
    return DETAILS


async def draft_details(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    try:
        value = clean_text(update.effective_message.text, 1500)
    except ValueError as exc:
        await update.effective_message.reply_text(str(exc))
        return DETAILS
    context.user_data["draft_form"]["details"] = value
    await update.effective_message.reply_text("Шаг 5 из 5. Как и когда покупатель получит товар/услугу? (до 400 символов).")
    return DELIVERY


async def draft_delivery(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    message = update.effective_message
    user = update.effective_user
    try:
        value = clean_text(message.text, 400)
    except ValueError as exc:
        await message.reply_text(str(exc))
        return DELIVERY
    draft = dict(context.user_data.get("draft_form", {}))
    draft["delivery"] = value
    try:
        draft_id = store.create(user.id, draft)
    except Exception:
        log.exception("Could not save draft for user %s", user.id)
        await message.reply_text("Не получилось сохранить черновик. Попробуй ещё раз позже.", reply_markup=main_keyboard())
        context.user_data.pop("draft_form", None)
        return ConversationHandler.END
    context.user_data.pop("draft_form", None)
    saved = store.get(user.id, draft_id)
    await message.reply_text(
        format_draft(saved) + "\n\nСкопируй текст и вручную создай лот на FunPay.",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Открыть FunPay и опубликовать вручную", url=FUNPAY_LOGIN_URL)],
            [InlineKeyboardButton("Создать ещё", callback_data="draft:new"),
             InlineKeyboardButton("Мои черновики", callback_data="drafts:list")],
            [InlineKeyboardButton("В меню", callback_data="home")],
        ]),
    )
    return ConversationHandler.END


async def cancel_draft(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    context.user_data.pop("draft_form", None)
    if update.callback_query:
        await update.callback_query.answer("Создание отменено")
        await update.callback_query.message.reply_text("Создание черновика отменено.", reply_markup=main_keyboard())
    elif update.effective_message:
        await update.effective_message.reply_text("Создание черновика отменено.", reply_markup=main_keyboard())
    return ConversationHandler.END


async def restart_from_conversation(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    await start(update, context)
    context.user_data.pop("draft_form", None)
    return ConversationHandler.END


async def menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if not query:
        return
    data = query.data or ""
    await query.answer()
    user = update.effective_user
    message = query.message

    if data in {"home", "menu"}:
        await message.reply_text("Главное меню FUNPAY LISTER:", reply_markup=main_keyboard())
        return

    if data == "help":
        await message.reply_text(
            "FUNPAY LISTER — бесплатный помощник для подготовки лотов.\n\n"
            "• Конструктор делает форматированный черновик.\n"
            "• «Мои черновики» открывает только сохранения твоего Telegram-аккаунта.\n"
            "• «Открыть FunPay» открывает официальную страницу.\n"
            "• «Подключить FunPay» открывает HTTPS-форму входа; пароль не вводится в Telegram и не сохраняется.\n\n"
            "После входа сохраняется зашифрованное состояние сессии. CAPTCHA/2FA может остановить автоматический вход. Автопубликация пока не включена.",
            reply_markup=back_keyboard(),
        )
        return

    if data == "funpay:connect":
        # Use the regular command helper but respond to the button callback.
        await connect_command(update, context)
        return

    if data == "funpay:status":
        await status_command(update, context)
        return

    if data == "funpay:disconnect":
        await disconnect_command(update, context)
        return

    if data == "how:works":
        await message.reply_text(
            "Как пользоваться:\n"
            "1. Нажми «Создать черновик лота» и ответь на 5 вопросов.\n"
            "2. Для серверного входа нажми «Подключить FunPay» и используй одноразовую HTTPS-страницу.\n"
            "3. Если сайт запросит CAPTCHA/2FA, автоматический вход может не завершиться.\n"
            "4. Черновик можно скопировать и опубликовать вручную.\n\n"
            "Важно: подключение лишь сохраняет зашифрованное состояние сессии. Автопубликация и автопроверка дальнейшего срока действия сессии пока не реализованы.",
            reply_markup=funpay_keyboard(),
        )
        return

    if data == "scenarios:list":
        await send_scene(message, "choose", "Примеры оформления лотов")
        await message.reply_text("Выбери тип предложения:", reply_markup=scenarios_keyboard())
        return

    if data.startswith("scenario:"):
        key = data.split(":", 1)[1]
        scenario = SCENARIOS.get(key)
        if not scenario:
            await message.reply_text("Неизвестный сценарий.", reply_markup=back_keyboard())
            return
        await send_scene(message, scenario["image"], scenario["title"])
        await message.reply_text(scenario["title"] + "\n\n" + scenario["text"], reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Создать свой черновик", callback_data="draft:new")],
            [InlineKeyboardButton("← К сценариям", callback_data="scenarios:list")],
            [InlineKeyboardButton("← В меню", callback_data="home")],
        ]))
        return

    if data == "drafts:list":
        drafts = store.list_for_user(user.id)
        if not drafts:
            await message.reply_text("Пока нет сохранённых черновиков. Нажми «Создать черновик лота».", reply_markup=main_keyboard())
            return
        rows = []
        for row in drafts:
            label = f"#{row['id']} · {row['title']} · {row['price']} ₽"
            rows.append([InlineKeyboardButton(label[:60], callback_data=f"draft:view:{row['id']}")])
        rows.append([InlineKeyboardButton("← В меню", callback_data="home")])
        await message.reply_text(f"Твои черновики ({len(drafts)}):", reply_markup=InlineKeyboardMarkup(rows))
        return

    if data.startswith("draft:view:"):
        try:
            draft_id = int(data.rsplit(":", 1)[1])
        except ValueError:
            await message.reply_text("Некорректный номер черновика.", reply_markup=back_keyboard())
            return
        row = store.get(user.id, draft_id)
        if not row:
            await message.reply_text("Черновик не найден.", reply_markup=back_keyboard())
            return
        await message.reply_text(format_draft(row), reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Открыть FunPay", url=FUNPAY_LOGIN_URL)],
            [InlineKeyboardButton("Удалить черновик", callback_data=f"draft:delete:{draft_id}")],
            [InlineKeyboardButton("← К черновикам", callback_data="drafts:list")],
        ]))
        return

    if data.startswith("draft:delete:"):
        try:
            draft_id = int(data.rsplit(":", 1)[1])
        except ValueError:
            await message.reply_text("Некорректный номер черновика.", reply_markup=back_keyboard())
            return
        deleted = store.delete(user.id, draft_id)
        await message.reply_text("Черновик удалён." if deleted else "Черновик уже отсутствует.", reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("Мои черновики", callback_data="drafts:list")],
            [InlineKeyboardButton("В меню", callback_data="home")],
        ]))
        return


# These references are assigned during webhook startup and accessed by the HTTP thread.
_HTTP_APPLICATION: Application | None = None
_HTTP_LOOP: asyncio.AbstractEventLoop | None = None
_WEBHOOK_PATH = ""
_WEBHOOK_SECRET = ""


def connection_page(title: str, message: str, success: bool = False) -> str:
    safe_title = html_escape(title)
    safe_message = html_escape(message).replace("\n", "<br>")
    accent = "#21c17a" if success else "#e3b34b"
    return f"""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{safe_title} · FUNPAY LISTER</title><style>
    body{{margin:0;background:#111216;color:#ececf1;font:16px system-ui,-apple-system,sans-serif;display:grid;min-height:100vh;place-items:center;padding:20px;box-sizing:border-box}}.card{{width:min(560px,100%);box-sizing:border-box;background:#1c1d23;border:1px solid #34353d;border-radius:18px;padding:28px}}h1{{font-size:24px;margin:0 0 14px}}p{{line-height:1.6;color:#c4c5cd}}.mark{{color:{accent};font-weight:700}}a{{color:#e9c36a}}.foot{{font-size:13px;color:#8e909b;margin-top:24px}}</style></head><body><main class="card"><div class="mark">FUNPAY LISTER by nezzx</div><h1>{safe_title}</h1><p>{safe_message}</p><p><a href="https://t.me/">Вернись в Telegram</a></p><div class="foot">Пароль не сохраняется и не выводится в логах. Сессионная cookie хранится только в зашифрованном виде. CAPTCHA/2FA может помешать автоматическому входу.</div></main></body></html>"""


def connection_form_page(token: str) -> str:
    # Token is generated by secrets.token_urlsafe and contains no HTML metacharacters.
    safe_token = html_escape(token, quote=True)
    return f"""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Подключить FunPay</title><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#111216;color:#ececf1;font:16px system-ui,-apple-system,sans-serif;display:grid;min-height:100vh;place-items:center;padding:20px}}.card{{width:min(480px,100%);background:#1c1d23;border:1px solid #34353d;border-radius:18px;padding:26px}}.brand{{color:#e9c36a;font-weight:700;letter-spacing:.04em}}h1{{font-size:25px;margin:18px 0 8px}}p{{line-height:1.55;color:#bfc1ca}}label{{display:block;font-size:14px;color:#d8d9df;margin:18px 0 7px}}input{{width:100%;padding:13px 14px;border-radius:10px;border:1px solid #41424b;background:#111216;color:#fff;font-size:16px;outline:none}}input:focus{{border-color:#d7ae51}}button{{width:100%;margin-top:22px;padding:14px;border:0;border-radius:10px;background:#e4bb5a;color:#171717;font-weight:800;font-size:16px;cursor:pointer}}.notice{{background:#272218;border:1px solid #66542b;padding:12px;border-radius:10px;font-size:13px;color:#e8d8ad}}.foot{{font-size:12px;color:#888b96;margin-top:20px;line-height:1.5}}</style></head><body><main class="card"><div class="brand">FUNPAY LISTER by nezzx</div><h1>Подключение аккаунта</h1><p>Это не сайт FunPay. Это страница подключения сервиса FUNPAY LISTER. После отправки пароль кратковременно поступит на Render-сервер, чтобы выполнить вход на официальный FunPay. Пароль не записывается в базу; сохраняется только зашифрованное состояние сессии.</p><div class="notice">Проверь HTTPS и домен своего Render-сервиса. Вводи пароль только если доверяешь владельцу сервиса. Не пересылай ссылку другим людям.</div><form method="post" action="/connect/{safe_token}" autocomplete="off"><label for="username">Имя пользователя или email FunPay</label><input id="username" name="username" type="text" maxlength="320" autocomplete="username" required><label for="password">Пароль FunPay</label><input id="password" name="password" type="password" maxlength="1024" autocomplete="current-password" required><button type="submit">Войти через FunPay</button></form><div class="foot">Одноразовая ссылка действует 15 минут. CAPTCHA/2FA может потребовать дополнительного шага, который автоматический режим не всегда поддерживает. Не вводи пароль, если страница выглядит подозрительно.</div></main></body></html>"""


class HealthHandler(BaseHTTPRequestHandler):
    def _reply(self, status: int, body: bytes) -> None:
        self.send_response(status)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _html(self, status: int, body: str) -> None:
        data = body.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("Pragma", "no-cache")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path.startswith("/connect/"):
            token = path.rsplit("/", 1)[-1]
            if auth_store.fernet is None:
                self._html(503, connection_page("Подключение отключено", "В Render не настроен SESSION_ENCRYPTION_KEY. Введённые данные не отправляйте."))
                return
            if auth_store.user_for_token(token) is None:
                self._html(410, connection_page("Ссылка устарела", "Ссылка недействительна, уже использована или истекла. Вернись в Telegram и запроси новую через /connect."))
                return
            self._html(200, connection_form_page(token))
            return
        if path not in ("/", "/healthz"):
            self._reply(404, b"Not found")
            return
        self._reply(200, b"FUNPAY LISTER is running")

    def do_POST(self) -> None:
        path = urlsplit(self.path).path
        if path.startswith("/connect/"):
            self._handle_connect_post(path.rsplit("/", 1)[-1])
            return
        if not _WEBHOOK_PATH or path != _WEBHOOK_PATH:
            self._reply(404, b"Not found")
            return
        if _WEBHOOK_SECRET:
            received = self.headers.get("X-Telegram-Bot-Api-Secret-Token", "")
            if not hmac.compare_digest(received, _WEBHOOK_SECRET):
                self._reply(403, b"Forbidden")
                return
        try:
            size = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self._reply(400, b"Bad Content-Length")
            return
        if size < 1 or size > 1_000_000:
            self._reply(413, b"Payload too large")
            return
        try:
            payload = json.loads(self.rfile.read(size))
            app = _HTTP_APPLICATION
            loop = _HTTP_LOOP
            if app is None or loop is None or not loop.is_running():
                self._reply(503, b"Bot starting")
                return
            update = Update.de_json(payload, app.bot)
            # asyncio.Queue must only be modified on its owning event loop.
            loop.call_soon_threadsafe(app.update_queue.put_nowait, update)
        except (json.JSONDecodeError, UnicodeDecodeError, TypeError, ValueError):
            self._reply(400, b"Invalid update")
            return
        except Exception:
            log.exception("Failed to accept Telegram webhook update")
            self._reply(500, b"Internal error")
            return
        self._reply(200, b"OK")

    def _handle_connect_post(self, token: str) -> None:
        if auth_store.fernet is None:
            self._html(503, connection_page("Подключение отключено", "В Render не настроен SESSION_ENCRYPTION_KEY."))
            return
        try:
            size = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self._html(400, connection_page("Ошибка формы", "Некорректный запрос."))
            return
        if size < 1 or size > 16_384:
            self._html(413, connection_page("Форма слишком большая", "Проверь значения и попробуй снова."))
            return
        content_type = self.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
        if content_type != "application/x-www-form-urlencoded":
            self._html(415, connection_page("Неверный формат", "Открой форму подключения из Telegram."))
            return
        try:
            raw = self.rfile.read(size).decode("utf-8")
            fields = parse_qs(raw, keep_blank_values=True, strict_parsing=False)
            username = fields.get("username", [""])[0]
            password = fields.get("password", [""])[0]
        except (UnicodeDecodeError, ValueError):
            self._html(400, connection_page("Ошибка формы", "Не удалось прочитать форму."))
            return
        # Consume the token only after a syntactically valid, bounded form body.
        user_id = auth_store.consume_token(token)
        if user_id is None:
            self._html(410, connection_page("Ссылка уже использована", "Запроси новую ссылку командой /connect в Telegram."))
            return
        success, message, state = attempt_login(username, password)
        # Drop local references to credentials as soon as the login attempt finishes.
        password = ""
        username_for_status = (username.strip()[:128] if success else "")
        if success and state:
            try:
                auth_store.save_session(user_id, username_for_status, state)
            except Exception:
                log.exception("Failed to save encrypted FunPay session; session payload omitted.")
                success = False
                message = "Вход выполнен, но не удалось безопасно сохранить сессию. Попробуй позже; пароль не сохранялся."
        status_code = 200 if success else 400
        title = "Подключено" if success else "Вход не подтверждён"
        self._html(status_code, connection_page(title, message + "\n\nВернись в Telegram и нажми «Статус аккаунта».", success=success))
        app = _HTTP_APPLICATION
        loop = _HTTP_LOOP
        if app is not None and loop is not None and loop.is_running():
            text_message = ("✅ FunPay-подключение создано. Нажми /status, чтобы увидеть статус." if success
                            else "⚠️ Попытка подключения FunPay не завершена. Открой страницу подключения ещё раз через /connect.")
            try:
                asyncio.run_coroutine_threadsafe(app.bot.send_message(chat_id=user_id, text=text_message), loop)
            except Exception:
                pass

    def log_message(self, fmt: str, *args: Any) -> None:
        # Do not log URL paths or request contents (the webhook path is secret).
        return


def start_http_server() -> ThreadingHTTPServer:
    port_text = os.getenv("PORT", "10000")
    try:
        port = int(port_text)
    except ValueError as exc:
        raise SystemExit("Переменная PORT должна быть числом.") from exc
    server = ThreadingHTTPServer(("0.0.0.0", port), HealthHandler)
    thread = threading.Thread(target=server.serve_forever, name="http-server", daemon=True)
    thread.start()
    log.info("HTTP health/webhook server listening on port %s", port)
    return server


async def run_webhook(application: Application, server: ThreadingHTTPServer, base_url: str) -> None:
    global _HTTP_APPLICATION, _HTTP_LOOP, _WEBHOOK_PATH, _WEBHOOK_SECRET
    _HTTP_APPLICATION = application
    _HTTP_LOOP = asyncio.get_running_loop()
    configured_secret = os.getenv("WEBHOOK_SECRET", "").strip()
    _WEBHOOK_SECRET = configured_secret or secrets.token_urlsafe(32)
    # Telegram secret_token allows only A-Z, a-z, 0-9, underscore and hyphen.
    _WEBHOOK_SECRET = re.sub(r"[^A-Za-z0-9_-]", "", _WEBHOOK_SECRET)[:128]
    _WEBHOOK_PATH = "/telegram/" + secrets.token_urlsafe(24).replace("-", "x").replace("_", "y")
    webhook_url = base_url.rstrip("/") + _WEBHOOK_PATH

    await application.initialize()
    await application.start()
    try:
        await application.bot.set_webhook(
            url=webhook_url,
            secret_token=_WEBHOOK_SECRET,
            allowed_updates=Update.ALL_TYPES,
            drop_pending_updates=False,
        )
        log.info("Telegram webhook registered; secret and URL omitted from logs.")
        await asyncio.Event().wait()
    finally:
        try:
            await application.bot.delete_webhook(drop_pending_updates=False)
        except Exception:
            log.warning("Could not delete webhook during shutdown.")
        if application.running:
            await application.stop()
        await application.shutdown()
        server.shutdown()
        server.server_close()


def build_application() -> Application:
    application = Application.builder().token(TELEGRAM_BOT_TOKEN).build()
    draft_conversation = ConversationHandler(
        entry_points=[CallbackQueryHandler(start_draft, pattern=r"^draft:new$")],
        states={
            TITLE: [MessageHandler(filters.TEXT & ~filters.COMMAND, draft_title)],
            CATEGORY: [MessageHandler(filters.TEXT & ~filters.COMMAND, draft_category)],
            PRICE: [MessageHandler(filters.TEXT & ~filters.COMMAND, draft_price)],
            DETAILS: [MessageHandler(filters.TEXT & ~filters.COMMAND, draft_details)],
            DELIVERY: [MessageHandler(filters.TEXT & ~filters.COMMAND, draft_delivery)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_draft),
            CallbackQueryHandler(cancel_draft, pattern=r"^draft:cancel$"),
            CommandHandler("start", restart_from_conversation),
        ],
        allow_reentry=True,
        per_chat=True,
        per_user=True,
        per_message=False,
    )
    application.add_handler(draft_conversation)
    application.add_handler(CommandHandler("start", start))
    application.add_handler(CommandHandler("help", help_command))
    application.add_handler(CommandHandler("connect", connect_command))
    application.add_handler(CommandHandler("status", status_command))
    application.add_handler(CommandHandler("disconnect", disconnect_command))
    application.add_handler(CommandHandler("cancel", cancel_draft))
    application.add_handler(CallbackQueryHandler(menu_callback))
    return application


def main() -> None:
    application = build_application()
    server = start_http_server()
    external_url = os.getenv("RENDER_EXTERNAL_URL", "").strip()
    if external_url:
        # Render's free web service can sleep when idle; webhook mode lets Telegram
        # wake the service on incoming updates instead of relying on long polling.
        log.info("Starting %s in Telegram webhook mode", BRAND)
        try:
            asyncio.run(run_webhook(application, server, external_url))
        except KeyboardInterrupt:
            pass
    else:
        # Local development fallback. On Render, RENDER_EXTERNAL_URL is set automatically.
        log.info("Starting %s in local polling mode", BRAND)
        try:
            application.run_polling(drop_pending_updates=False, allowed_updates=Update.ALL_TYPES)
        finally:
            server.shutdown()
            server.server_close()


if __name__ == "__main__":
    main()
